"""Band-Selected Descent: decoding the address of a Pythagorean triple.

The algorithm reads the generator word of a node of the Barning-Hall tree
using only three linear comparisons per level -- no factorisation, no
residues, no square roots.
"""

from __future__ import annotations

from typing import List, Tuple

Triple = Tuple[int, int, int]


def branch_letter(a: int, b: int) -> int:
    """Return 1, 2 or 3 according to the leg-ratio band of (a, b)."""
    if 4 * a < 3 * b:
        return 1
    if 4 * b < 3 * a:
        return 3
    return 2


def inverse_generator(i: int, t: Triple) -> Triple:
    """Apply the inverse of the i-th Barning-Hall generator (i in 1,2,3)."""
    a, b, c = t
    if i == 1:
        return (a + 2 * b - 2 * c, -2 * a - b + 2 * c, -2 * a - 2 * b + 3 * c)
    if i == 2:
        return (a + 2 * b - 2 * c, 2 * a + b - 2 * c, -2 * a - 2 * b + 3 * c)
    return (-a - 2 * b + 2 * c, 2 * a + b - 2 * c, -2 * a - 2 * b + 3 * c)


def generator(i: int, t: Triple) -> Triple:
    """Apply the i-th Barning-Hall generator (i in 1,2,3)."""
    a, b, c = t
    if i == 1:
        return (a - 2 * b + 2 * c, 2 * a - b + 2 * c, 2 * a - 2 * b + 3 * c)
    if i == 2:
        return (a + 2 * b + 2 * c, 2 * a + b + 2 * c, 2 * a + 2 * b + 3 * c)
    return (-a + 2 * b + 2 * c, -2 * a + b + 2 * c, -2 * a + 2 * b + 3 * c)


def decode_address(t: Triple, root: Triple = (3, 4, 5)) -> List[int]:
    """Return the full generator word of t, read from ratio bands alone.

    The word is returned with the LAST generator applied first, matching
    the order in which the bands are read.  Termination is guaranteed
    because each descent strictly decreases the hypotenuse.
    """
    word: List[int] = []
    cur = t
    while cur != root:
        i = branch_letter(cur[0], cur[1])
        word.append(i)
        nxt = inverse_generator(i, cur)
        if nxt[2] >= cur[2] or min(nxt) <= 0:
            raise ValueError(f"{t} is not a positive primitive triple of the tree")
        cur = nxt
    return word


def encode_address(word: List[int], root: Triple = (3, 4, 5)) -> Triple:
    """Inverse of decode_address: apply the word, last letter first."""
    cur = root
    for i in reversed(word):
        cur = generator(i, cur)
    return cur


if __name__ == "__main__":
    w = [2, 1, 3, 3, 2, 1]
    t = encode_address(w)
    print("word    ", w)
    print("triple  ", t)
    print("decoded ", decode_address(t))
    assert decode_address(t) == w
